    '#ifdef FSHIGHPRECISION\n    precision highp float;\n#else\n    precision mediump float;\n#endif\n#include \'ShaderUtils.glsl\';\n#include \'Lighting.glsl\';\n\nuniform vec3 u_CameraPos;\nuniform DirectionLight u_DirectionLight;\n\nuniform sampler2D u_MainTex;\nuniform sampler2D u_NormalTex;\nuniform sampler2D u_ORMTex;\nuniform sampler2D u_RampTex;\nuniform sampler2D u_MatCapTex;\nuniform float u_NormalScale;\nuniform vec4 u_BaseColor;\n\nuniform float u_ORMPower;\nuniform vec4 u_ORMScale;\n\nuniform float u_RampOffset;\nuniform float u_RampMapSkin;\nuniform float u_RampScale;\n\nuniform float u_CubeStrength;\nuniform vec4 u_SpecMetalColor;\n\nuniform vec4 u_RimColor;\nuniform float u_RimPower;\nuniform float u_RimSoftness;\nuniform float u_RimIntensity;\nuniform float u_RimLightEffect;\n\nuniform vec4 u_OutlineColor;\n\nvarying vec2 v_Texcoord;\nvarying vec3 v_PositionWorld;\nvarying vec3 v_Normal;\nvarying vec3 v_Tangent;\nvarying vec3 v_biNormal;\nvarying mat4 v_View;\n\nvec3 ComputeF0(float specular, vec3 baseColor, float metallic){ return lerp(vec3(specular * 0.08), baseColor, metallic); }\nfloat SmithJointGGXVisibilityTerm(float NdotL, float NdotV, float roughness){\n    float a = roughness;\n    float a2 = a * a;\n    float lambdaV = NdotL * sqrt((-NdotV * a2 + NdotV) * NdotV + a2);\n    float lambdaL = NdotV * sqrt((-NdotL * a2 + NdotL) * NdotL + a2);\n    return 0.5 / (lambdaV + lambdaL + 1e-5);\n}\nfloat GGXTerm(float NdotH, float roughness){\n    float a2 = roughness * roughness;\n    float d = (NdotH * a2 - NdotH) * NdotH + 1.0;\n    return 0.31830988618 * a2 / (d * d + 0.0000001);\n}\nvec3 FresnelTerm(vec3 c, float cosA){ return c + (1.0 - c) * pow(1.0 - cosA, 5.0); }\nfloat GetSpecularOcclusion(float metallic, float roughness, float occlusion){\n    return lerp(occlusion, 1.0, metallic * (1.0 - roughness) * (1.0 - roughness));\n}\nfloat ComputeEnvMapMipFromRoughness(float roughness){\n    float perceptualRoughness = roughness;\n    perceptualRoughness = perceptualRoughness * (1.7 - 0.7 * perceptualRoughness);\n    return perceptualRoughness * 6.0;\n}\nvec3 EnvBRDF(vec3 specColor, float roughness, float NdotV){\n    vec4 c0 = vec4(-1.0, -0.0275, -0.572, 0.022);\n    vec4 c1 = vec4(1.0, 0.0425, 1.04, -0.04);\n    vec4 r = roughness * c0 + c1;\n    float a004 = min(r.x * r.x, exp2(-9.28 * NdotV)) * r.x + r.y;\n    vec2 AB = vec2(-1.04, 1.04) * a004 + r.zw;\n    AB.y *= saturate(50.0 * specColor.g);\n    return specColor * AB.x + AB.y;\n}\n\nvoid main(){\n    vec3 worldViewDir = normalize(u_CameraPos - v_PositionWorld);\n    worldViewDir.x *= -1.0;\n    vec3 worldLightDir = normalize(u_DirectionLight.Direction);\n    worldLightDir.yz *= -1.0;\n    vec3 lightColor = u_DirectionLight.Color.rgb * 3.2;\n    mat3 TBN = mat3(normalize(v_Tangent), normalize(v_biNormal), normalize(v_Normal));\n    vec3 normalTangent = UnpackNormal(texture2D(u_NormalTex, v_Texcoord));\n    normalTangent.xy *= u_NormalScale;\n    normalTangent.z = sqrt(1.0 - saturate(dot(normalTangent.xy, normalTangent.xy)));\n    vec3 worldNormal = normalize(TBN * normalTangent);\n    vec3 worldHalfDir = normalize(worldViewDir + worldLightDir);\n\n    vec4 albedo = texture2D(u_MainTex, v_Texcoord);\n    vec3 orm = pow(texture2D(u_ORMTex, v_Texcoord).rgb, vec3(u_ORMPower)) * u_ORMScale.rgb;\n    float ao = orm.r;\n    float roughness = orm.g;\n    float metallic = orm.b;\n\n    vec3 diffColor = lerp(albedo, vec4(0.0), metallic).xyz;\n    vec3 specColor = ComputeF0(0.5, albedo.xyz, metallic);\n\n    float NoH = saturate(dot(worldNormal, worldHalfDir));\n    // float VoH = saturate(dot(worldViewDir, worldHalfDir));\n    float NoV = saturate(dot(worldNormal, worldViewDir));\n    float NoL = saturate(dot(worldNormal, worldLightDir));\n    float LoH = saturate(dot(worldLightDir, worldHalfDir));\n    \n    vec3 diffuseTerm = diffColor * 0.31830988618;\n\n    \n    float V = SmithJointGGXVisibilityTerm(NoL, NoV, roughness);\n    float D = GGXTerm(NoH, roughness * roughness);\n    vec3 F = FresnelTerm(specColor, LoH);\n    vec3 specularTerm = F * V * D;\n    specularTerm = clamp(specularTerm, 0.0, 10.0);\n    float specRange = saturate(D * V);\n    vec4 specRampCol = texture2D(u_RampTex, vec2(specRange, 0.7));\n    specularTerm = F * clamp(specRampCol.rgb, 0.0, 10.0);\n\n    float x = max(0.0, NoL) + u_RampOffset;\n    vec2 UVramp = vec2(x, u_RampMapSkin);\n    vec3 ShadowRamp1 = texture2D(u_RampTex, UVramp).rgb;\n    \n#ifdef DEF_RampTex\n    vec3 directLighting = 3.14159265359 * diffuseTerm * lightColor * ShadowRamp1 * u_RampScale;\n#else\n    vec3 directLighting = 3.14159265359 * diffuseTerm * lightColor * NoL * u_RampScale;\n#endif\n    directLighting += 3.14159265359 * specularTerm * lightColor * NoL * u_SpecMetalColor.rgb;\n    \n    vec3 indirectDiffuse = diffColor * ao;//max(0.0, ShadeSH9(vec4(worldNormal, 1.0))) * diffColor * ao;\n    \n    float specOcclusion = GetSpecularOcclusion(metallic, roughness, ao);\n    float envMip = ComputeEnvMapMipFromRoughness(roughness);\n\n    vec3 viewNormal = normalize(v_View * vec4(worldNormal, 0.0)).xyz;\n    viewNormal.x *= -1.0;\n    vec2 uv = viewNormal.xy * 0.5 + 0.5;\n    uv.y = 1.0 - uv.y;\n    vec4 matcap = texture2D(u_MatCapTex, uv, envMip - 1.0);\n    vec3 envMap = matcap.xyz * ShadowRamp1;\n    \n#ifdef DEF_MatCapTex\n    vec3 indirectSpecular = envMap * specOcclusion * EnvBRDF(specColor, roughness, NoV) * u_CubeStrength;\n#else\n    vec3 indirectSpecular = vec3(0.0);\n#endif\n\n    vec3 indirectLighting = indirectDiffuse + indirectSpecular;\n\n#ifdef DEF_RIM_ON\n    vec3 dir = worldLightDir;\n    dir.y = 0.0;\n    dir *= -u_RimLightEffect;\n    worldViewDir = normalize(worldViewDir + dir);\n    float ndotv = dot(normalize(worldNormal), worldViewDir);\n    float rim = 1.0 - saturate(ndotv);\n\n    float range = 1.0 - u_RimPower;\n    range = max(0.001, range);\n    float softness = 1.0 - u_RimSoftness;\n    softness = max(0.001, softness);\n    rim = smoothstep(range - softness, range + softness, rim);\n    vec3 rimColor = rim * u_RimColor.rgb * u_RimIntensity * 0.1;\n    vec3 finalColor = directLighting + indirectLighting + rimColor;\n#else\n    vec3 rimColor = vec3(1.0);\n    vec3 finalColor = directLighting + indirectLighting;\n#endif\n#ifdef DEF_OutlineBounds\n    finalColor *= u_OutlineColor.rgb;\n    finalColor *= u_BaseColor.rgb;\n    finalColor *= lightColor;\n    finalColor *= rimColor;\n    gl_FragColor = vec4(finalColor, 1.0 * u_OutlineColor.a * u_BaseColor.a);\n#else\n    gl_FragColor = vec4(finalColor * u_BaseColor.rgb, 1.0 * u_BaseColor.a);\n#endif\n}', 
